import{_ as n,C as t,o as l,c as o,j as s,a as p,E as c,a2 as r}from"./chunks/framework.C2TvIV46.js";const v=JSON.parse('{"title":"trigger","description":"","frontmatter":{},"headers":[],"relativePath":"language/elements/trigger.md","filePath":"language/elements/trigger.md"}'),i={name:"language/elements/trigger.md"};function d(g,a,m,b,u,h){const e=t("AvailabilityCard");return l(),o("div",null,[a[0]||(a[0]=s("h1",{id:"trigger",tabindex:"-1"},[p("trigger "),s("a",{class:"header-anchor",href:"#trigger","aria-label":'Permalink to "trigger"'},"​")],-1)),c(e,{reach:"yes",halo4:"yes",h2a:"yes"}),a[1]||(a[1]=r(`<p>The core executable element. Each trigger is an event handler: the engine evaluates its conditions, and if they all pass, it executes the trigger&#39;s actions. When any condition fails, execution <strong>halts</strong> for the current evaluation — subsequent conditions and actions in the same trigger are skipped.</p><p>Compile-time limits including trigger count are listed under <strong>Limits</strong> on each <a href="/MegaloEvolved/beta/docs/versions/">megalo version page</a> — for example <a href="/MegaloEvolved/beta/docs/versions/49/#limits">49</a>, <a href="/MegaloEvolved/beta/docs/versions/73/#limits">73</a>, <a href="/MegaloEvolved/beta/docs/versions/107/#limits">107</a>, or <a href="/MegaloEvolved/beta/docs/versions/107-mcc/#limits">107 (MCC)</a>. <code>trigger</code> is <strong>full-script-only</strong> — it cannot be added in <a href="/MegaloEvolved/beta/docs/language/base-files">base-derived scripts</a>.</p><h2 id="syntax" tabindex="-1">Syntax <a class="header-anchor" href="#syntax" aria-label="Permalink to &quot;Syntax&quot;">​</a></h2><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>trigger &lt;kind&gt; [&lt;name&gt;]</span></span>
<span class="line"><span>	[&lt;conditions and actions&gt;]</span></span>
<span class="line"><span>end</span></span></code></pre></div><ul><li><strong>kind</strong> — determines the execution context (see <a href="#trigger-kinds">Trigger kinds</a>)</li><li><strong>name</strong> — optional; unique within the script. When omitted, the trigger is anonymous.</li></ul><div class="language-megalo vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">megalo</span><pre class="megalo-edit vp-code" tabindex="0"><code><span class="line"><span class="megalo-keyword">trigger</span><span class="megalo-text"> </span><span class="megalo-enumMember">initialization</span></span>
<span class="line"><span class="megalo-text">	</span><span class="megalo-comment">; runs once when the variant loads</span></span>
<span class="line"><span class="megalo-keyword">end</span></span>
<span class="line"><wbr></span>
<span class="line"><span class="megalo-keyword">trigger</span><span class="megalo-text"> </span><span class="megalo-type">player</span></span>
<span class="line"><span class="megalo-text">	</span><span class="megalo-keyword">condition </span><span class="megalo-function">player_died</span><span class="megalo-text"> </span><span class="megalo-variable">current_player</span><span class="megalo-text"> </span><span class="megalo-enumMember">enemy</span></span>
<span class="line"><span class="megalo-text">	</span><span class="megalo-keyword">action </span><span class="megalo-function">set_score</span><span class="megalo-text"> </span><span class="megalo-keyword">add</span><span class="megalo-text"> </span><span class="megalo-number">1</span><span class="megalo-text"> </span><span class="megalo-parameter">player</span><span class="megalo-text"> killing_player</span></span>
<span class="line"><span class="megalo-keyword">end</span></span>
<span class="line"><wbr></span>
<span class="line"><span class="megalo-keyword">trigger</span><span class="megalo-text"> bro_spawn_location</span></span>
<span class="line"><span class="megalo-text">	</span><span class="megalo-keyword">action </span><span class="megalo-function">object_set_invincibility</span><span class="megalo-text"> </span><span class="megalo-variable">current_object</span><span class="megalo-text"> </span><span class="megalo-variable">true</span></span>
<span class="line"><span class="megalo-keyword">end</span></span></code></pre></div><h2 id="trigger-kinds" tabindex="-1">Trigger kinds <a class="header-anchor" href="#trigger-kinds" aria-label="Permalink to &quot;Trigger kinds&quot;">​</a></h2><p>The kind controls which implicit context variables are available and how often the trigger runs.</p><table tabindex="0"><thead><tr><th>Kind</th><th>Context variable</th><th>Runs…</th></tr></thead><tbody><tr><td><code>general</code></td><td>(none)</td><td>Once per tick, globally</td></tr><tr><td><code>player</code></td><td><code>current_player</code></td><td>Once per player, per tick</td></tr><tr><td><code>random_player</code></td><td><code>current_player</code></td><td>Once per tick, for a random player</td></tr><tr><td><code>team</code></td><td><code>current_team</code></td><td>Once per team, per tick</td></tr><tr><td><code>object</code></td><td><code>current_object</code></td><td>Once per object, per tick</td></tr><tr><td><code>initialization</code></td><td>(none)</td><td>Once when the variant loads</td></tr><tr><td><code>local_initialization</code></td><td>(none)</td><td>Once per machine at load</td></tr><tr><td><code>host_migration</code></td><td>(none)</td><td>After host migration</td></tr><tr><td><code>double_migration</code></td><td>(none)</td><td>After double host migration</td></tr><tr><td><code>object_death</code></td><td><code>current_object</code></td><td>When a bound object is destroyed</td></tr><tr><td><code>local</code></td><td>(none)</td><td>Local-only scope</td></tr><tr><td><code>pregame</code></td><td>(none)</td><td>During lobby / pre-game phase</td></tr></tbody></table><h3 id="object-filter-triggers" tabindex="-1">Object-filter triggers <a class="header-anchor" href="#object-filter-triggers" aria-label="Permalink to &quot;Object-filter triggers&quot;">​</a></h3><p>When the trigger kind is a <a href="/MegaloEvolved/beta/docs/language/elements/map-object"><code>map_object</code></a> label name, the trigger runs once per matching object on the map, with <code>current_object</code> set to that object:</p><div class="language-megalo vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">megalo</span><pre class="megalo-edit vp-code" tabindex="0"><code><span class="line"><span class="megalo-keyword">map_object</span><span class="megalo-text"> </span><span class="megalo-variable">invasion_respawn_phase_1</span></span>
<span class="line"><span class="megalo-text">	</span><span class="megalo-parameter">label</span><span class="megalo-text"> </span><span class="megalo-string">&quot;inv_res_p1&quot;</span></span>
<span class="line"><span class="megalo-keyword">end</span></span>
<span class="line"><wbr></span>
<span class="line"><span class="megalo-keyword">trigger</span><span class="megalo-text"> </span><span class="megalo-variable">invasion_respawn_phase_1</span></span>
<span class="line"><span class="megalo-text">	</span><span class="megalo-keyword">action </span><span class="megalo-function">set_respawn_filter</span><span class="megalo-text"> </span><span class="megalo-variable">current_object</span><span class="megalo-text"> </span><span class="megalo-enumMember">no_one</span></span>
<span class="line"><span class="megalo-text">	</span><span class="megalo-keyword">action </span><span class="megalo-function">object_set_invincibility</span><span class="megalo-text"> </span><span class="megalo-variable">current_object</span><span class="megalo-text"> </span><span class="megalo-variable">true</span></span>
<span class="line"><span class="megalo-keyword">end</span></span></code></pre></div><p>This is equivalent to an <code>object</code>-kind trigger filtered to objects matching that label or type.</p><h2 id="action-scope" tabindex="-1">Action scope <a class="header-anchor" href="#action-scope" aria-label="Permalink to &quot;Action scope&quot;">​</a></h2><p>Inside <code>trigger</code> blocks and <code>action for_each</code> sub-triggers, the body is an <strong>action scope</strong>. Only these keywords are valid:</p><table tabindex="0"><thead><tr><th>Element</th><th>Purpose</th></tr></thead><tbody><tr><td><code>condition</code></td><td>A predicate; halts the block if false</td></tr><tr><td><code>or</code></td><td>Chains the previous and next condition with logical OR</td></tr><tr><td><code>action</code></td><td>An imperative statement</td></tr><tr><td><code>temporary</code></td><td>Declares a temporary variable for this block</td></tr><tr><td><a href="/MegaloEvolved/beta/docs/language/elements/begin"><code>begin</code></a></td><td>Opens an explicit sub-block (rare)</td></tr><tr><td><code>end</code></td><td>Closes the current scope or sub-block</td></tr></tbody></table><div class="language-megalo vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">megalo</span><pre class="megalo-edit vp-code" tabindex="0"><code><span class="line"><span class="megalo-keyword">trigger</span><span class="megalo-text"> </span><span class="megalo-type">player</span></span>
<span class="line"><span class="megalo-text">	</span><span class="megalo-keyword">condition </span><span class="megalo-function">player_died</span><span class="megalo-text"> </span><span class="megalo-variable">current_player</span><span class="megalo-text"> </span><span class="megalo-enumMember">enemy</span><span class="megalo-text"> </span><span class="megalo-keyword">or</span></span>
<span class="line"><span class="megalo-text">	</span><span class="megalo-keyword">condition </span><span class="megalo-function">if</span><span class="megalo-text"> </span><span class="megalo-variable">current_player</span><span class="megalo-operator">.</span><span class="megalo-text">is_leader </span><span class="megalo-keyword">equal_to</span><span class="megalo-text"> </span><span class="megalo-variable">true</span></span>
<span class="line"><span class="megalo-text">	</span><span class="megalo-keyword">action </span><span class="megalo-function">set_score</span><span class="megalo-text"> </span><span class="megalo-keyword">add</span><span class="megalo-text"> </span><span class="megalo-number">1</span><span class="megalo-text"> </span><span class="megalo-parameter">player</span><span class="megalo-text"> killing_player</span></span>
<span class="line"><span class="megalo-keyword">end</span></span></code></pre></div><p><strong><code>or</code> chaining</strong> — <code>or</code> must appear immediately after a <code>condition</code>, and must be followed by another <code>condition</code>. Only conditions can follow <code>or</code>; actions or other keywords produce a compile error.</p><p><strong>Capacity</strong> — A script may contain at most <strong>512</strong> conditions and <strong>1024</strong> actions across all triggers.</p><p><strong><code>temporary</code> in pregame</strong> — <code>temporary</code> declarations are not allowed inside <code>pregame</code> triggers.</p><p><strong><code>begin</code> / <code>end</code></strong> — Explicit sub-blocks implement if/elseif-style branching. See <a href="/MegaloEvolved/beta/docs/language/elements/begin">begin</a>.</p><h2 id="execution-model" tabindex="-1">Execution model <a class="header-anchor" href="#execution-model" aria-label="Permalink to &quot;Execution model&quot;">​</a></h2><p>Triggers execute in the order they are defined in the script, on the same tick. For <code>player</code>, <code>team</code>, and <code>object</code> triggers, the engine iterates over every instance and runs the trigger body once per instance.</p><p>Within a trigger, conditions and actions are evaluated <strong>top to bottom</strong>:</p><ol><li>Each <code>condition</code> is tested in order.</li><li>If a condition evaluates to <strong>false</strong>, the trigger <strong>halts</strong> — remaining conditions and actions are skipped for this evaluation.</li><li>If all conditions pass (or there are no conditions), actions run in order.</li></ol><p>Actions can appear before conditions. Conditions after an action still halt the trigger if they fail — actions that already ran are not undone.</p><div class="language-megalo vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">megalo</span><pre class="megalo-edit vp-code" tabindex="0"><code><span class="line"><span class="megalo-keyword">trigger</span><span class="megalo-text"> </span><span class="megalo-type">player</span></span>
<span class="line"><span class="megalo-text">	</span><span class="megalo-keyword">action </span><span class="megalo-function">timer_set_rate</span><span class="megalo-text"> </span><span class="megalo-variable">current_player</span><span class="megalo-operator">.</span><span class="megalo-text">game_start_vo </span><span class="megalo-number">1</span></span>
<span class="line"><wbr></span>
<span class="line"><span class="megalo-text">	</span><span class="megalo-keyword">condition </span><span class="megalo-function">if</span><span class="megalo-text"> </span><span class="megalo-variable">current_player</span><span class="megalo-operator">.</span><span class="megalo-text">heard_game_start </span><span class="megalo-operator">==</span><span class="megalo-text"> </span><span class="megalo-number">0</span></span>
<span class="line"><span class="megalo-text">	</span><span class="megalo-keyword">condition </span><span class="megalo-function">timer_expired</span><span class="megalo-text"> </span><span class="megalo-variable">current_player</span><span class="megalo-operator">.</span><span class="megalo-text">game_start_vo</span></span>
<span class="line"><wbr></span>
<span class="line"><span class="megalo-text">	</span><span class="megalo-keyword">action </span><span class="megalo-function">submit_incident</span><span class="megalo-text"> </span><span class="megalo-enumMember">game_start_slayer</span><span class="megalo-text"> </span><span class="megalo-parameter">player</span><span class="megalo-text"> </span><span class="megalo-variable">current_player</span><span class="megalo-text"> </span><span class="megalo-parameter">player</span><span class="megalo-text"> </span><span class="megalo-variable">none</span></span>
<span class="line"><span class="megalo-text">	</span><span class="megalo-keyword">action </span><span class="megalo-function">set</span><span class="megalo-text"> </span><span class="megalo-variable">current_player</span><span class="megalo-operator">.</span><span class="megalo-text">heard_game_start </span><span class="megalo-operator">=</span><span class="megalo-text"> </span><span class="megalo-number">1</span></span>
<span class="line"><span class="megalo-keyword">end</span></span></code></pre></div><h2 id="interval" tabindex="-1">Interval <a class="header-anchor" href="#interval" aria-label="Permalink to &quot;Interval&quot;">​</a></h2><p>By default, triggers run every tick. An <code>interval</code> line limits execution frequency:</p><div class="language-megalo vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">megalo</span><pre class="megalo-edit vp-code" tabindex="0"><code><span class="line"><span class="megalo-keyword">trigger</span><span class="megalo-text"> </span><span class="megalo-enumMember">general</span></span>
<span class="line"><span class="megalo-text">	interval </span><span class="megalo-number">5</span></span>
<span class="line"><span class="megalo-text">	</span><span class="megalo-comment">; runs once every 5 seconds instead of every tick</span></span>
<span class="line"><span class="megalo-keyword">end</span></span></code></pre></div><h2 id="for-each-sub-triggers" tabindex="-1">for_each sub-triggers <a class="header-anchor" href="#for-each-sub-triggers" aria-label="Permalink to &quot;for_each sub-triggers&quot;">​</a></h2><p>The <code>action for_each</code> statement embeds a nested trigger body that runs once per target:</p><div class="language-megalo vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">megalo</span><pre class="megalo-edit vp-code" tabindex="0"><code><span class="line"><span class="megalo-text">action for_each player</span></span>
<span class="line"><span class="megalo-text">	condition if current_player</span><span class="megalo-operator">.</span><span class="megalo-text">team equal_to attackers</span></span>
<span class="line"><span class="megalo-text">	action set current_player</span><span class="megalo-operator">.</span><span class="megalo-text">fireteam set_to </span><span class="megalo-number">0</span></span>
<span class="line"><span class="megalo-keyword">end</span></span>
<span class="line"><wbr></span>
<span class="line"><span class="megalo-text">action for_each invasion_objective</span></span>
<span class="line"><span class="megalo-text">	condition if current_object</span><span class="megalo-operator">.</span><span class="megalo-text">user_data equal_to k_territory_id_main_switch</span></span>
<span class="line"><span class="megalo-text">	action navpoint_set_visible current_object everyone</span></span>
<span class="line"><span class="megalo-keyword">end</span></span></code></pre></div><table tabindex="0"><thead><tr><th>Target</th><th>Iterates over…</th></tr></thead><tbody><tr><td><code>player</code></td><td>Every player</td></tr><tr><td><code>team</code></td><td>Every team</td></tr><tr><td><code>object</code></td><td>Every object</td></tr><tr><td><code>general</code></td><td>Runs once (no iteration)</td></tr><tr><td><code>&lt;map_object label&gt;</code></td><td>Every object matching that filter</td></tr></tbody></table><p>Inside a <code>for_each</code> block, conditions that evaluate to false <strong>skip the current iteration</strong> (like <code>continue</code> in C) rather than halting the entire trigger.</p><div class="language-megalo vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">megalo</span><pre class="megalo-edit vp-code" tabindex="0"><code><span class="line"><span class="megalo-text">action for_each invasion_objective</span></span>
<span class="line"><span class="megalo-text">	temporary object buy_zone current_object</span></span>
<span class="line"><wbr></span>
<span class="line"><span class="megalo-text">	action for_each player</span></span>
<span class="line"><span class="megalo-text">		condition object_in_area current_player current_object</span></span>
<span class="line"><span class="megalo-text">		action set total_in_area add </span><span class="megalo-number">1</span></span>
<span class="line"><span class="megalo-text">	</span><span class="megalo-keyword">end</span></span>
<span class="line"><span class="megalo-keyword">end</span></span></code></pre></div><h2 id="temporary-variables" tabindex="-1">Temporary variables <a class="header-anchor" href="#temporary-variables" aria-label="Permalink to &quot;Temporary variables&quot;">​</a></h2><p>Temporary variables can be declared at the top of a trigger or inside a <code>for_each</code> or <code>begin</code> block:</p><div class="language-megalo vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">megalo</span><pre class="megalo-edit vp-code" tabindex="0"><code><span class="line"><span class="megalo-keyword">trigger</span><span class="megalo-text"> </span><span class="megalo-type">player</span></span>
<span class="line"><span class="megalo-text">	</span><span class="megalo-keyword">temporary </span><span class="megalo-type">number</span><span class="megalo-text"> </span><span class="megalo-variable">temp</span><span class="megalo-text"> </span><span class="megalo-number">0</span></span>
<span class="line"><span class="megalo-text">	</span><span class="megalo-keyword">temporary </span><span class="megalo-type">object</span><span class="megalo-text"> </span><span class="megalo-variable">my_body</span><span class="megalo-text"> </span><span class="megalo-variable">current_player</span></span>
<span class="line"><wbr></span>
<span class="line"><span class="megalo-text">	</span><span class="megalo-keyword">condition </span><span class="megalo-function">player_died</span><span class="megalo-text"> </span><span class="megalo-variable">current_player</span><span class="megalo-text"> </span><span class="megalo-enumMember">enemy</span></span>
<span class="line"><span class="megalo-text">	</span><span class="megalo-keyword">temporary </span><span class="megalo-type">player</span><span class="megalo-text"> </span><span class="megalo-variable">killer</span><span class="megalo-text"> </span><span class="megalo-variable">none</span></span>
<span class="line"><span class="megalo-text">	</span><span class="megalo-keyword">action </span><span class="megalo-function">player_death_get_killing_player</span><span class="megalo-text"> </span><span class="megalo-variable">current_player</span><span class="megalo-text"> </span><span class="megalo-variable">killer</span></span>
<span class="line"><span class="megalo-keyword">end</span></span></code></pre></div><p>See <a href="/MegaloEvolved/beta/docs/language/variable-model#temporary-variables">Variable model — Temporary variables</a>.</p><h2 id="special-triggers" tabindex="-1">Special triggers <a class="header-anchor" href="#special-triggers" aria-label="Permalink to &quot;Special triggers&quot;">​</a></h2><ul><li><strong><code>initialization</code></strong> — runs once when the gametype loads. Used for setup before gameplay (objectives, timers, intro sounds).</li><li><strong><code>host_migration</code></strong> — runs after the host changes mid-game. Used to restore state lost during migration.</li><li><strong><code>pregame</code></strong> — runs during the lobby phase. Only a whitelisted subset of conditions and actions is valid; <code>temporary</code> is not allowed.</li></ul><div class="language-megalo vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">megalo</span><pre class="megalo-edit vp-code" tabindex="0"><code><span class="line"><span class="megalo-keyword">trigger</span><span class="megalo-text"> </span><span class="megalo-enumMember">initialization</span></span>
<span class="line"><span class="megalo-text">	</span><span class="megalo-keyword">action </span><span class="megalo-function">play_sound</span><span class="megalo-text"> </span><span class="megalo-parameter">team</span><span class="megalo-text"> </span><span class="megalo-variable">defenders</span><span class="megalo-text"> </span><span class="megalo-enumMember">bone_cv_ph1_intro</span></span>
<span class="line"><span class="megalo-text">	</span><span class="megalo-keyword">action </span><span class="megalo-function">timer_set_rate</span><span class="megalo-text"> buy_zone_timer </span><span class="megalo-number">1</span></span>
<span class="line"><span class="megalo-keyword">end</span></span>
<span class="line"><wbr></span>
<span class="line"><span class="megalo-keyword">trigger</span><span class="megalo-text"> </span><span class="megalo-enumMember">host_migration</span></span>
<span class="line"><span class="megalo-text">	</span><span class="megalo-keyword">action for_each </span><span class="megalo-text">invasion_gates</span></span>
<span class="line"><span class="megalo-text">		</span><span class="megalo-keyword">condition </span><span class="megalo-function">if</span><span class="megalo-text"> </span><span class="megalo-variable">current_object</span><span class="megalo-operator">.</span><span class="megalo-property">user_data</span><span class="megalo-text"> </span><span class="megalo-keyword">equal_to</span><span class="megalo-text"> buy_zone</span><span class="megalo-operator">.</span><span class="megalo-property">user_data</span></span>
<span class="line"><span class="megalo-text">		</span><span class="megalo-keyword">action </span><span class="megalo-function">delete_object</span><span class="megalo-text"> </span><span class="megalo-variable">current_object</span></span>
<span class="line"><span class="megalo-text">	</span><span class="megalo-keyword">end</span></span>
<span class="line"><span class="megalo-keyword">end</span></span></code></pre></div><h2 id="see-also" tabindex="-1">See also <a class="header-anchor" href="#see-also" aria-label="Permalink to &quot;See also&quot;">​</a></h2><ul><li><a href="/MegaloEvolved/beta/docs/language/elements/trigger/condition">condition</a> — condition syntax and operators</li><li><a href="/MegaloEvolved/beta/docs/language/elements/trigger/action">action</a> — action syntax and families</li><li><a href="/MegaloEvolved/beta/docs/language/elements/begin">begin</a> — explicit sub-blocks</li><li><a href="/MegaloEvolved/beta/docs/language/examples">Example scripts</a> — annotated trigger walkthroughs</li></ul>`,45))])}const x=n(i,[["render",d]]);export{v as __pageData,x as default};
